Use a circular buffer with a head index and an explicit element count, so all 17 slots are usable and overflow is rejected without modifying the queue. The invariant is that head identifies the next element to pop, count stays between 0 and 17, and the next insertion index is (head + count) modulo 17. Empty means count is 0 and full means count is 17, so matching circular indices never create ambiguity; compile with C++17 and run without defining NDEBUG to keep the assertions enabled.

```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) {
            return false;
        }
        data_[(head_ + count_) % capacity] = value;
        ++count_;
        return true;
    }

    bool pop(int& value) {
        if (count_ == 0) {
            return false;
        }
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    BoundedFIFO queue;
    int value = -1;

    // Empty pop fails and does not alter the output argument.
    assert(queue.empty());
    assert(!queue.pop(value));
    assert(value == -1);

    // Every slot is usable.
    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
        assert(queue.size() == static_cast<std::size_t>(i + 1));
    }
    assert(queue.full());

    // The 18th insertion fails; draining verifies unchanged contents.
    assert(!queue.push(999));
    assert(queue.size() == 17);
    for (int i = 0; i < 17; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    // Move the head, then insert across the physical array boundary.
    for (int i = 0; i < 12; ++i) {
        assert(queue.push(i));
    }
    for (int i = 0; i < 9; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    for (int i = 12; i < 26; ++i) {
        assert(queue.push(i));
    }
    assert(queue.full());
    assert(!queue.push(999));
    assert(queue.size() == 17);

    // Both insertion and removal wrap, preserving FIFO order.
    for (int i = 9; i < 26; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    std::cout << "All tests passed\n";
}

// Compile and run:
// g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo && ./fifo
```

The lower median is 4: sorting conceptually gives [1,2,4,4,7,9], and the lower of the two middle elements is at zero-based index 2. The function copies the caller’s array before using `std::nth_element`, so the original remains unchanged; empty input throws `std::invalid_argument`.

For a nonempty array of size n, select index `(n - 1) / 2` using integer division. If n = 2m + 1, this equals m, the sole middle index; if n = 2m, it equals m − 1, the lower middle index. `std::nth_element` places at that index the value that would occupy it in sorted order, including when duplicates exist, so the returned value is the lower median.

```cpp
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

int lowerMedian(const std::vector<int>& input) {
    if (input.empty()) {
        throw std::invalid_argument("lowerMedian requires nonempty input");
    }

    std::vector<int> values = input;
    const std::size_t index = (values.size() - 1) / 2;
    auto middle = values.begin() +
                  static_cast<std::vector<int>::difference_type>(index);
    std::nth_element(values.begin(), middle, values.end());
    return *middle;
}

int main() {
    const auto check = [](const std::vector<int>& input, int expected) {
        const std::vector<int> original = input;
        const int result = lowerMedian(input);
        assert(result == expected);
        assert(input == original);
    };

    // Requested example: duplicates and even size.
    check({9, 1, 4, 4, 7, 2}, 4);

    // Additional duplicate-heavy case.
    check({2, 2, 1, 2, 3}, 2);

    // Odd size: sorted order is [1, 3, 5, 7, 9].
    check({9, 1, 7, 3, 5}, 5);

    // Even size with distinct middle values: choose 2, not 8.
    check({10, 2, 8, 1}, 2);

    // Singleton.
    check({42}, 42);

    // Empty input is explicitly rejected and remains unchanged.
    const std::vector<int> empty;
    bool rejected = false;
    try {
        (void)lowerMedian(empty);
    } catch (const std::invalid_argument&) {
        rejected = true;
    }
    assert(rejected);
    assert(empty.empty());

    std::cout << "All tests passed\n";
}

// Compile and run with assertions enabled (do not define NDEBUG):
// g++ -std=c++17 -Wall -Wextra -pedantic median.cpp -o median && ./median
```

No. Retrying with a stale `desired` can report success without incrementing the counter, losing an increment.

For a concrete execution, start with the counter at 0:
1. Threads A and B each load `expected = 0` and compute `desired = 1` before their loops.
2. A successfully compares 0 and stores 1, then returns.
3. B compares its expected 0 against the actual 1. The comparison fails, updates B’s `expected` to 1, and leaves its `desired` at 1.
4. B retries, successfully compares 1 and stores 1, then returns. Both increments have finished, but the final counter is 1 instead of 2.

The fix is to recompute `desired` from the current `expected` before every attempt. A spurious failure performs no store and updates `expected` with the observed value, which may be unchanged; the loop recomputes and retries safely. Relaxed ordering is sufficient for this standalone counter because it needs atomic updates, not synchronization of unrelated data; the test reads the result after joining every thread.

```cpp
#include <atomic>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <thread>
#include <vector>

void increment(std::atomic<std::uint64_t>& counter) {
    std::uint64_t expected = counter.load(std::memory_order_relaxed);
    for (;;) {
        // Recompute after every failure, including spurious failures.
        const std::uint64_t desired = expected + 1;
        if (counter.compare_exchange_weak(
                expected, desired,
                std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return;
        }
        // Failure has overwritten expected with the observed value.
    }
}

int main() {
    constexpr unsigned threadCount = 8;
    constexpr std::uint64_t incrementsPerThread = 100000;
    constexpr std::uint64_t expectedTotal =
        threadCount * incrementsPerThread;

    // This test stays far below uint64_t overflow. In general, unsigned
    // increments wrap modulo 2^64; this is not an unbounded counter.
    std::atomic<std::uint64_t> counter{0};
    std::atomic<bool> start{false};
    std::vector<std::thread> workers;
    workers.reserve(threadCount);

    for (unsigned t = 0; t < threadCount; ++t) {
        workers.emplace_back([&] {
            while (!start.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }
            for (std::uint64_t i = 0; i < incrementsPerThread; ++i) {
                increment(counter);
            }
        });
    }

    start.store(true, std::memory_order_release);
    for (auto& worker : workers) {
        worker.join();
    }

    const std::uint64_t actual = counter.load(std::memory_order_relaxed);
    assert(actual == expectedTotal);
    if (actual != expectedTotal) {
        std::cerr << "Incorrect count: " << actual
                  << "; expected " << expectedTotal << '\n';
        return 1;
    }
    std::cout << "All tests passed; final count = " << actual << '\n';
}

// Compile and run with assertions enabled (do not define NDEBUG):
// g++ -std=c++17 -O2 -Wall -Wextra -pedantic -pthread counter.cpp -o counter
// ./counter
```
